{
  "name": "@amykit/plugin-plan-check",
  "version": "0.6.0",
  "description": "The quality bar for a drafted plan: the repository's own check, run in its checkout.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/plan-check"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/workflow-note-to-plan": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { CommandRunner, Git } from "@amykit/core";
import { AttemptOutcome, PlanCheck } from "@amykit/workflow-note-to-plan";

export interface PlanCommandCheckConfig {
  /**
   * The checks to run, per repository, falling back to the `default` entry.
   * Written as shell command lines, because that is how a repository's own
   * contributor docs write them.
   */
  commands: Readonly<Record<string, readonly string[]>>;
  timeoutMs?: number;
}

/**
 * The quality bar for a drafted plan: the repository's own check, run in its
 * checkout.
 *
 * Nobody had to invent a rubric here. The repository being written into
 * already has one — a plan with no exit condition, or one missing from the
 * ordered list, is refused by it — and it is the same one a human contributor
 * meets. What comes back is kept verbatim, because it becomes the finding the
 * agent is sent back with.
 *
 * It stops at the first failure rather than collecting all of them, so the
 * agent gets one clear thing to fix instead of a wall of noise where the
 * second half is caused by the first.
 */
export class PlanCommandCheck implements PlanCheck {
  constructor(
    private readonly runner: CommandRunner,
    private readonly git: Git,
    private readonly config: PlanCommandCheckConfig,
  ) {}

  async check(repo: string, workId?: string): Promise<AttemptOutcome> {
    const commands = this.config.commands[repo] ?? this.config.commands.default ?? [];

    if (commands.length === 0) {
      return {
        ok: false,
        output: `no check is configured for ${repo}, so nothing can vouch for this plan`,
        at: new Date().toISOString(),
      };
    }

    const transcript: string[] = [];

    for (const command of commands) {
      const result = await this.runner.run("sh", ["-c", command], {
        cwd: this.git.pathFor(repo, workId),
        timeoutMs: this.config.timeoutMs,
      });

      const output = [result.stdout, result.stderr].filter(Boolean).join("\n").trim();

      if (!result.ok) {
        transcript.push(`$ ${command}\nexited ${result.exitCode}\n\n${output}`);
        return { ok: false, output: transcript.join("\n\n"), at: new Date().toISOString() };
      }

      transcript.push(`$ ${command}\nok`);
    }

    return { ok: true, output: transcript.join("\n"), at: new Date().toISOString() };
  }
}

import { BRANCH_SETTINGS, ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  ...BRANCH_SETTINGS,
  commands: {
    type: "record",
    description:
      "the check commands per repository, with a `default` fallback. `sf check` is the whole quality bar in a repository that has one",
    default: { default: ["sf check"] },
  },
  timeoutMs: {
    type: "number",
    description: "how long one check may run before it is given up on",
    default: 10 * 60 * 1000,
  },
} satisfies ConfigSchema;

export { PlanCommandCheck } from "./PlanCommandCheck.js";
export type { PlanCommandCheckConfig } from "./PlanCommandCheck.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";

import { definePlugin } from "@amykit/core";
import { PlanCommandCheck } from "./PlanCommandCheck.js";
import { configSchema } from "./config.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-plan-check",
  configSchema,
  register(registry, ctx) {
    // The gate (and the agent it hands paths to) runs where the work runs:
    // with a worktree port mounted, that is the item's own tree.
    const { git } = ctx.checkouts();

    // The action and the port together, which is what the registry asks of a
    // plugin adding an action the core does not ship: an action nobody can
    // execute is a promise the machine cannot keep. `check-plan` is not in
    // the core catalogue because nothing has yet shown it is general — a
    // second workflow needing it is what would move it there.
    registry.action(
      "check-plan",
      { port: "plan-check", method: "check" },
      new PlanCommandCheck(ctx.runner, git, {
        commands: ctx.config.commands as Record<string, string[]>,
        timeoutMs: ctx.config.timeoutMs,
      }),
    );
  },
});
